arguments.command:
cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh DATE: one reminder per booking of the day, from the listing.
set -u
if [ $# -ne 1 ]; then echo "usage: remind.sh DATE" >&2; exit 2; fi
out=$(bash "$(dirname "$0")/list.sh" "$1") || exit $?
if [ -z "$out" ]; then echo "no bookings: $1"; exit 0; fi
printf '%s\n' "$out" | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/remind.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'no bookings: 2026-01-02' ] || { echo "a day without bookings"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-01)" = 'reminder to x: aoi 2026-01-01 10:00-11:00' ] || { echo "a day with a booking"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ -z "$(bash src/remind.sh 2>/dev/null)" ] || { echo "usage should go to stderr only"; fail=1; }
BOOKINGS=/nonexistent/bookings.tsv bash src/remind.sh 2026-01-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a missing bookings file should exit 2"; fail=1; }
rm -f "$t"; exit $fail
EOF
